```st
FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state        : INT := 0;
    openBtnPrev  : BOOL := FALSE;
    closeBtnPrev : BOOL := FALSE;
    bInit        : BOOL := FALSE;
END_VAR
VAR
    risingOpen  : BOOL;
    risingClose : BOOL;
END_VAR

IF NOT bInit THEN
    state := 0;
    bInit := TRUE;
END_IF

risingOpen  := openBtn AND NOT openBtnPrev;
risingClose := closeBtn AND NOT closeBtnPrev;

openBtnPrev  := openBtn;
closeBtnPrev := closeBtn;

motorUp   := FALSE;
motorDown := FALSE;
errorFlag := (state = 3);

CASE state OF
    0:
        IF risingOpen AND NOT openLimit THEN
            state := 1;
        ELSIF risingClose AND NOT closeLimit THEN
            state := 2;
        END_IF

    1:
        motorUp := TRUE;
        IF obstacle THEN
            motorUp   := FALSE;
            errorFlag := TRUE;
            state := 3;
        ELSIF openLimit THEN
            state := 0;
        END_IF

    2:
        motorDown := TRUE;
        IF obstacle THEN
            motorDown := FALSE;
            motorUp   := TRUE;
            state := 1;
        ELSIF closeLimit THEN
            state := 0;
        END_IF

    3:
        IF risingOpen AND risingClose AND NOT obstacle THEN
            state := 0;
        END_IF
END_CASE

END_FUNCTION_BLOCK
```

