FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state       : INT := 0; // 0=IDLE,1=OPENING,2=CLOSING,3=FAULT
    openBtnPrev : BOOL := FALSE;
    closeBtnPrev: BOOL := FALSE;
    bInit       : BOOL := FALSE;
END_VAR
VAR
    risingOpen  : BOOL;
    risingClose : BOOL;
END_VAR

// Initialization
IF NOT bInit THEN
    state := 0; // IDLE
    bInit := TRUE;
END_IF

// Rising edge detection
risingOpen  := openBtn AND NOT openBtnPrev;
risingClose := closeBtn AND NOT closeBtnPrev;

// Update button history
openBtnPrev  := openBtn;
closeBtnPrev := closeBtn;

// Default outputs
motorUp   := FALSE;
motorDown := FALSE;
errorFlag := (state = 3); // FAULT

CASE state OF
    0: // IDLE
        IF risingOpen AND NOT openLimit THEN
            state := 1; // OPENING
        ELSIF risingClose AND NOT closeLimit THEN
            state := 2; // CLOSING
        END_IF

    1: // OPENING
        motorUp := TRUE;
        IF obstacle THEN
            motorUp   := FALSE;
            errorFlag := TRUE;
            state := 3; // FAULT
        ELSIF openLimit THEN
            state := 0; // IDLE
        END_IF

    2: // CLOSING
        motorDown := TRUE;
        IF obstacle THEN
            motorDown := FALSE;
            motorUp   := TRUE;
            state := 1; // OPENING
        ELSIF closeLimit THEN
            state := 0; // IDLE
        END_IF

    3: // FAULT
        // Reset only on rising edge of both buttons when obstacle cleared
        IF risingOpen AND risingClose AND NOT obstacle THEN
            state := 0; // IDLE
        END_IF
END_CASE

END_FUNCTION_BLOCK
```

